package org.jlinalg.cli;

import java.io.IOException;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.sequence.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Complete source/native count, preprocessing and original PCA geometry audits. */
final class LeafCutterWorkflowAudit {
    private LeafCutterWorkflowAudit() { }
    static final class Meter {
        final long maximum;long used;
        Meter(long maximum){this.maximum=maximum;}
        void spend(long n)throws IOException{require(!Thread.currentThread().isInterrupted()&&n>=0&&n<=maximum-used,"Native audit interrupted or operation capacity exceeded; no partial result admitted");used+=n;}
    }
    static double number(Object value)throws IOException{return finite(value,-Double.MAX_VALUE,Double.MAX_VALUE);}
    static List<String> strings(Object value)throws IOException{var result=new ArrayList<String>();for(Object item:list(value))result.add(text(item));return List.copyOf(result);}
    static List<Double> vector(Object value)throws IOException{var result=new ArrayList<Double>();for(Object item:list(value))result.add(number(item));return List.copyOf(result);}
    static double[][] matrix(Object value)throws IOException{var rows=list(value);double[][] result=new double[rows.size()][];for(int i=0;i<rows.size();i++){var row=vector(rows.get(i));result[i]=new double[row.size()];for(int j=0;j<row.size();j++)result[i][j]=row.get(j);}return result;}
    static List<List<Long>> integers(long[][] values){var result=new ArrayList<List<Long>>();for(long[] row:values){var r=new ArrayList<Long>();for(long value:row)r.add(value);result.add(List.copyOf(r));}return List.copyOf(result);}
    static void close(double actual,double expected,double absolute,double relative,String cause,Meter meter)throws IOException {meter.spend(1);require(Double.isFinite(actual)&&Double.isFinite(expected)&&Math.abs(actual-expected)<=Math.max(absolute,relative*Math.max(Math.abs(actual),Math.abs(expected))),cause+"; expected="+expected+", actual="+actual);}
    static void same(Object expected,Object actual,String path,double absolute,double relative,Meter meter)throws IOException {
        meter.spend(1);if(expected==null){require(actual==null,"Original missing state differs: "+path);return;}
        if(expected instanceof Map<?,?> map){var found=object(actual);require(map.keySet().equals(found.keySet()),"Complete original field family differs: "+path);for(var entry:map.entrySet())same(entry.getValue(),found.get(entry.getKey()),path+"/"+entry.getKey(),absolute,relative,meter);}
        else if(expected instanceof List<?> values){var found=list(actual);require(values.size()==found.size(),"Complete original length differs: "+path);for(int i=0;i<values.size();i++)same(values.get(i),found.get(i),path+"/"+i,absolute,relative,meter);}
        else if(expected instanceof Long||expected instanceof Integer)require(integer(actual,Long.MIN_VALUE,Long.MAX_VALUE)==((Number)expected).longValue(),"Exact original integer differs: "+path);
        else if(expected instanceof Number n)close(number(actual),n.doubleValue(),absolute,relative,"Original numeric differs: "+path,meter);
        else require(expected.equals(actual),"Original identifier/type/state/order differs: "+path);
    }
    static Map<String,Object> analyze(Map<String,Object> c,Path home,Map<String,Path> captured,LeafCutterWorkflowRequest.Request request,List<String> warnings,Meter meter)throws Exception {
        String id=text(c.get("id")),kind=text(c.get("kind"));var summary=new LinkedHashMap<String,Object>();summary.put("id",id);summary.put("kind",kind);long before=meter.used;
        if(kind.equals("cluster")||kind.equals("pipeline"))summary.put("clustering",clustering(c,home,captured,request,warnings,meter));
        if(kind.equals("phenotype")||c.containsKey("phenotype"))summary.put("phenotype",phenotype(c,home.resolve("phenotype"),request,warnings,meter));
        if(kind.equals("differential")||c.containsKey("differential"))summary.put("differential",LeafCutterDifferentialAudit.analyze(c,home.resolve("differential"),request,warnings,meter));summary.put("native_audit_operations",meter.used-before);return summary;
    }
    private static Map<String,Object> clustering(Map<String,Object> c,Path home,Map<String,Path> captured,LeafCutterWorkflowRequest.Request request,List<String> warnings,Meter meter)throws Exception {
        var op=object(c.get("cluster"));var options=new LeafCutterClusters.Options(integer(op.get("maximum_intron_length"),1,Long.MAX_VALUE),integer(op.get("minimum_reads"),0,Long.MAX_VALUE),finite(op.get("minimum_ratio"),0,1),bool(op.get("check_chromosomes")));var samples=LeafCutterWorkflowInputs.junctions(c,captured,request.inputBytes());long inputRows=0;for(var sample:samples)inputRows+=sample.rows().size();meter.spend(inputRows);var limits=new LeafCutterClusters.Limits(100000,10000000,1000000,request.auditOperations(),10000000);var result=LeafCutterClusters.compute(samples,options,limits);Path source=home.resolve("original");same(clusterRows(result.pooled()),originalClusters(source.resolve("leaf_pooled"),request.outputBytes()),"pooled",0,0,meter);same(clusterRows(result.refined()),originalClusters(source.resolve("leaf_refined"),request.outputBytes()),"refined",0,0,meter);var ratio=LeafCutterWorkflowInputs.matrix(source.resolve("leaf_perind.counts.gz"),true,request.outputBytes());var numerator=LeafCutterWorkflowInputs.matrix(source.resolve("leaf_perind_numers.counts.gz"),false,request.outputBytes());require(result.samples().equals(ratio.samples())&&result.samples().equals(numerator.samples())&&result.rows().size()==ratio.introns().size()&&ratio.introns().equals(numerator.introns()),"Complete original cluster count axes differ");var rows=new ArrayList<Object>();
        for(int i=0;i<result.rows().size();i++){var row=result.rows().get(i);require(row.id().equals(ratio.introns().get(i)),"Original clustering row ID/order differs");for(int j=0;j<result.samples().size();j++){meter.spend(2);require(row.numerators().get(j)==ratio.numerators()[i][j]&&row.numerators().get(j)==numerator.numerators()[i][j]&&row.denominators().get(j)==ratio.denominators()[i][j],"Original numerator/denominator or integer precision differs");}rows.add(Map.of("id",row.id(),"numerators",row.numerators(),"denominators",row.denominators()));}
        var decisions=new ArrayList<Object>();for(var d:result.inputDispositions())decisions.add(Map.of("sample_ordinal",d.sampleOrdinal(),"row_ordinal",d.rowOrdinal(),"original_line",d.source().originalLine(),"disposition",d.disposition().name()));NextflowFiles.writeJson(home.resolve("native-clustering.json"),Map.of("samples",result.samples(),"pooled",clusterRows(result.pooled()),"refined",clusterRows(result.refined()),"rows",rows,"input_dispositions",decisions));warnings.addAll(result.warnings());if(result.rows().isEmpty())warnings.add("Clustering case "+c.get("id")+" returned the complete original empty retained family; no splicing signal is inferred.");return Map.of("source_rows",inputRows,"retained_rows",result.rows().size(),"sample_count",result.samples().size(),"refined_clusters",result.refined().size(),"per_case_native_traversal_capacity",request.auditOperations());
    }
    private static List<Object> clusterRows(List<LeafCutterClusters.Cluster> clusters){var result=new ArrayList<Object>();for(var cluster:clusters){var rows=new ArrayList<Object>();for(var row:cluster.introns())rows.add(Map.of("start",row.intron().start(),"end",row.intron().end(),"reads",row.reads()));result.add(Map.of("ordinal",cluster.ordinal(),"axis",List.of(cluster.axis().chromosome(),cluster.axis().strand()),"introns",rows));}return result;}
    private static List<Object> originalClusters(Path file,long maximum)throws IOException {var result=new ArrayList<Object>();for(String line:LeafCutterWorkflowInputs.lines(file,maximum)){String[] fields=LeafCutterWorkflowInputs.fields(line),axis=fields[0].split(":",-1);require(axis.length==2,"Original cluster axis is ambiguous");var rows=new ArrayList<Object>();for(int i=1;i<fields.length;i++){String[] f=fields[i].split(":",-1);require(f.length==3,"Original cluster coordinate/read family malformed");rows.add(Map.of("start",LeafCutterWorkflowInputs.integerText(f[0]),"end",LeafCutterWorkflowInputs.integerText(f[1]),"reads",LeafCutterWorkflowInputs.integerText(f[2])));}result.add(Map.of("ordinal",result.size()+1,"axis",List.of(axis),"introns",rows));}return result;}
    private static Map<String,Object> phenotype(Map<String,Object> c,Path home,LeafCutterWorkflowRequest.Request request,List<String> warnings,Meter meter)throws Exception {
        var options=object(c.get("phenotype"));var input=LeafCutterWorkflowInputs.matrix(home.resolve("input.counts.gz"),true,request.outputBytes());var nativeResult=LeafCutterPhenotypes.compute(input.samples(),LeafCutterWorkflowInputs.phenotypeRows(input),new LeafCutterPhenotypes.Options(strings(options.get("blacklist"))),LeafCutterPhenotypes.Limits.defaults());var source=LeafCutterWorkflowRuntime.read(home.resolve("source-report.json"),Math.toIntExact(Math.min(request.outputBytes(),268435456)));var expected=phenotypeResult(nativeResult);var selected=new LinkedHashMap<String,Object>();for(String key:expected.keySet())selected.put(key,source.get(key));same(expected,selected,"complete-phenotype",2e-14,2e-14,meter);NextflowFiles.writeJson(home.resolve("native-phenotype.json"),expected);var sorted=nativeResult.sortedForSourceFiles();var family=new HashSet<String>(Set.of("input.counts.gz","blacklist.txt","launch-original.py","input.counts.gz.ave","input.counts.gz_prepare.sh","source-report.json","native-phenotype.json"));var commands=new HashSet<String>();
        for(String chrom:nativeResult.chromosomesSeen()){
            var originalOrder=new ArrayList<LeafCutterPhenotypes.Kept>();for(var row:nativeResult.kept())if(row.chromosome().equals(chrom))originalOrder.add(row);var qqOrder=new ArrayList<LeafCutterPhenotypes.Kept>();for(var row:sorted)if(row.chromosome().equals(chrom))qqOrder.add(row);
            for(String prefix:List.of("phen_","qqnorm_")){String name="input.counts.gz."+prefix+chrom;family.add(name);var lines=LeafCutterWorkflowInputs.lines(home.resolve(name),request.outputBytes());var rows=prefix.equals("phen_")?originalOrder:qqOrder;var header=new ArrayList<String>(List.of("#Chr","start","end","ID"));header.addAll(input.samples());require(List.of(LeafCutterWorkflowInputs.fields(lines.get(0))).equals(header)&&lines.size()==rows.size()+1,"Original phenotype/QQ header or complete row family differs");for(int i=0;i<rows.size();i++){String[] f=LeafCutterWorkflowInputs.fields(lines.get(i+1));var row=rows.get(i);require(f.length==input.samples().size()+4&&List.of(f[0],f[1],f[2],f[3]).equals(List.of(row.chromosome(),row.startText(),row.endText(),row.id())),"Original phenotype coordinates/order differ; original .phen and sorted QQ orders are distinct");var values=prefix.equals("phen_")?row.imputedRatios():row.inverseNormalScores();for(int j=0;j<values.size();j++)close(Double.parseDouble(f[j+4]),values.get(j),2e-14,2e-14,"Original phenotype/QQ value differs",meter);}}
            commands.add("bgzip -f input.counts.gz.qqnorm_"+chrom);commands.add("tabix -p bed input.counts.gz.qqnorm_"+chrom+".gz");
        }
        var averages=LeafCutterWorkflowInputs.lines(home.resolve("input.counts.gz.ave"),request.outputBytes());require(averages.size()==nativeResult.kept().size(),"Original average-summary family incomplete");for(int i=0;i<averages.size();i++){String[] f=LeafCutterWorkflowInputs.fields(averages.get(i));var row=nativeResult.kept().get(i);require(f.length==4&&f[0].equals(row.id()),"Original average-summary row order differs");close(Double.parseDouble(f[1]),row.observedMinimum(),2e-14,2e-14,"Original observed minimum differs",meter);close(Double.parseDouble(f[2]),row.observedMaximum(),2e-14,2e-14,"Original observed maximum differs",meter);close(Double.parseDouble(f[3]),row.observedMean(),2e-14,2e-14,"Original observed mean differs",meter);}var shell=LeafCutterWorkflowInputs.lines(home.resolve("input.counts.gz_prepare.sh"),request.outputBytes());require(shell.size()==commands.size()&&new HashSet<>(shell).equals(commands),"Original optional indexing commands differ; they were not executed");int pcs=Math.toIntExact(integer(options.get("pcs"),0,1000));long pca=0;
        if(pcs>0){family.add("input.counts.gz.PCs");pca=pca(home,source.get("PCA"),nativeResult,pcs,request.outputBytes(),warnings,meter);}else require(source.get("PCA")==null,"Unexpected original PCA state");try(var files=Files.list(home)){var names=new HashSet<String>();for(Path file:files.toList())if(Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS))names.add(file.getFileName().toString());require(names.equals(family),"Complete original phenotype file family has missing/extra members");}warnings.addAll(nativeResult.warnings());warnings.add("Original phenotype indexing script is retained but bgzip/tabix are separate tools and were not executed. PCA treats introns as observations and samples as features; no transpose or biological interpretation is inferred.");return Map.of("source_rows",input.introns().size(),"retained_rows",nativeResult.kept().size(),"sample_count",input.samples().size(),"PCA_equations",pca);
    }
    private static Map<String,Object> phenotypeResult(LeafCutterPhenotypes.Result result){var rows=new ArrayList<Object>();for(var row:result.originalRows()){var pairs=new ArrayList<Object>();for(var count:row.counts())pairs.add(List.of(count.numerator(),count.denominator()));rows.add(Map.of("id",row.id(),"counts",pairs));}var decisions=new ArrayList<Object>();for(var d:result.decisions()){var m=new LinkedHashMap<String,Object>();m.put("ordinal",d.ordinal());m.put("id",d.original().id());m.put("disposition",d.disposition().name());m.put("source_ratios",d.sourceRatios());m.put("missing",d.missing());m.put("observed_mean",d.observedMean());m.put("observed_minimum",d.observedMinimum());m.put("observed_maximum",d.observedMaximum());m.put("population_stddev",d.populationStddev());decisions.add(m);}var kept=new ArrayList<Object>();for(var d:result.kept()){var m=new LinkedHashMap<String,Object>();m.put("input_ordinal",d.inputOrdinal());m.put("id",d.id());m.put("chromosome",d.chromosome());m.put("start_text",d.startText());m.put("end_text",d.endText());m.put("start",d.start());m.put("imputed_ratios",d.imputedRatios());m.put("standardized",d.standardized());m.put("inverse_normal_scores",d.inverseNormalScores());m.put("observed_mean",d.observedMean());m.put("observed_minimum",d.observedMinimum());m.put("observed_maximum",d.observedMaximum());m.put("scaling_mean",d.scalingMean());m.put("population_stddev",d.populationStddev());kept.add(m);}return Map.of("samples",result.samples(),"original_rows",rows,"chromosomes_seen",result.chromosomesSeen(),"decisions",decisions,"kept",kept,"sorted_ids",result.sortedForSourceFiles().stream().map(LeafCutterPhenotypes.Kept::id).toList());}
    private static long pca(Path home,Object raw,LeafCutterPhenotypes.Result input,int requested,long maximum,List<String> warnings,Meter meter)throws IOException {
        long before=meter.used;var p=object(raw);int n=input.kept().size(),m=input.samples().size(),k=Math.min(requested,m);require(integer(p.get("observations"),2,Integer.MAX_VALUE)==n&&integer(p.get("features"),1,Integer.MAX_VALUE)==m,"Original PCA matrix orientation/dimensions differ");double[][] components=matrix(p.get("components")),scores=matrix(p.get("scores"));var mean=vector(p.get("mean"));var singular=vector(p.get("singular_values"));var variance=vector(p.get("explained_variance"));var ratios=list(p.get("explained_variance_ratio"));String solver=text(p.get("solver"));require(components.length==k&&scores.length==n&&mean.size()==m&&singular.size()==k&&variance.size()==k&&ratios.size()==k&&Set.of("full","randomized").contains(solver),"Complete original PCA component/score/variance family differs");for(double[] row:components)require(row.length==m,"Ragged PCA components");for(double[] row:scores)require(row.length==k,"Ragged PCA scores");var lines=LeafCutterWorkflowInputs.lines(home.resolve("input.counts.gz.PCs"),maximum);var header=new ArrayList<String>();header.add("id");header.addAll(input.samples());require(lines.size()==k+1&&List.of(LeafCutterWorkflowInputs.fields(lines.get(0))).equals(header),"Original PCA component file header/dimensions differ");double total=0;
        for(int j=0;j<m;j++){double sum=0;for(var row:input.kept()){sum+=row.inverseNormalScores().get(j);meter.spend(1);}close(mean.get(j),sum/n,2e-10,2e-10,"Original PCA centering differs",meter);for(var row:input.kept()){double d=row.inverseNormalScores().get(j)-mean.get(j);total+=d*d;meter.spend(1);}}
        total/=n-1;for(int a=0;a<k;a++){String[] fields=LeafCutterWorkflowInputs.fields(lines.get(a+1));require(fields.length==m+1&&fields[0].equals(Integer.toString(a+1)),"Original PCA component row order differs");for(int j=0;j<m;j++)close(Double.parseDouble(fields[j+1]),components[a][j],1e-13,1e-13,"Original PCA file and public replay differ",meter);for(int b=0;b<k;b++){double dot=0;for(int j=0;j<m;j++){dot+=components[a][j]*components[b][j];meter.spend(1);}close(dot,a==b?1:0,2e-10,2e-10,"PCA components not orthonormal",meter);}double projectedNorm=0;for(int i=0;i<n;i++){double value=0;for(int j=0;j<m;j++){value+=(input.kept().get(i).inverseNormalScores().get(j)-mean.get(j))*components[a][j];meter.spend(1);}close(scores[i][a],value,2e-10,2e-10,"Original PCA score/projection differs",meter);projectedNorm+=scores[i][a]*scores[i][a];}double square=singular.get(a)*singular.get(a);close(variance.get(a),square/(n-1),2e-10,2e-10,"Original PCA singular-value variance differs",meter);if(solver.equals("full"))close(projectedNorm,square,2e-10,2e-10,"Original full PCA spectral norm differs",meter);else require(projectedNorm+1e-10>=square,"Original randomized PCA norm bound differs");if(total==0){require(object(ratios.get(a)).equals(Map.of("state","NaN")),"Original undefined variance ratio was hidden/repaired");warnings.add("PCA has an original undefined NaN explained-variance ratio in "+home+". Do not replace it with zero or interpret zero-rank components as biological covariates.");}else close(number(ratios.get(a)),variance.get(a)/total,2e-10,2e-10,"Original PCA explained-variance ratio differs",meter);}return meter.used-before;
    }
}
